pub fn quadtree_node_reset<F>(node: &mut QuadtreeNode, key_free: F)
where
    F: FnOnce(Option<Box<dyn std::any::Any>>),
{
    if let Some(point) = node.point.take() {
        quadtree_point_free(point);
    }
    key_free(node.key.take());
}

pub fn quadtree_walk<F, G>(root: &QuadtreeNode, descent: F, ascent: G)
where
    F: Fn(&QuadtreeNode),
    G: Fn(&QuadtreeNode),
{
    descent(root);
    if let Some(nw) = &root.nw {
        quadtree_walk(nw, &descent, &ascent);
    }
    if let Some(ne) = &root.ne {
        quadtree_walk(ne, &descent, &ascent);
    }
    if let Some(sw) = &root.sw {
        quadtree_walk(sw, &descent, &ascent);
    }
    if let Some(se) = &root.se {
        quadtree_walk(se, &descent, &ascent);
    }
    ascent(root);
}

pub fn node_contains(outer: &QuadtreeNode, it: &QuadtreePoint) -> bool {
    if let Some(bounds) = &outer.bounds {
        bounds.nw.x < it.x && bounds.nw.y > it.y && bounds.se.x > it.x && bounds.se.y < it.y
    } else {
