pub fn insert(tree: &mut Quadtree, root: &mut QuadtreeNode, point: Box<QuadtreePoint>, key: Box<dyn std::any::Any>) -> bool {
    if quadtree_node_isempty(root) {
        root.point = Some(point);
        root.key = Some(key);
        return true;
    } else if quadtree_node_isleaf(root) {
        if let Some(ref existing_point) = root.point {
            if existing_point.x == point.x && existing_point.y == point.y {
                reset_node(tree, root);
                root.point = Some(point);
                root.key = Some(key);
                return false;
            } else {
                if !split_node(tree, root) {
                    return false;
                }
                return insert(tree, root, point, key);
            }
        }
        return true;
    } else if quadtree_node_ispointer(root) {
        if let Some(quadrant) = get_quadrant(root, &point) {
            return insert(tree, quadrant, point, key);
        }
        return false;
    }
    false
}

pub fn split_node(tree: &mut Quadtree, node: &mut QuadtreeNode) -> bool {
    let x = node.bounds.as_ref().unwrap().nw.x;
    let y = node.bounds.as_ref().unwrap().nw.y;
    let hw = node.bounds.as_ref().unwrap().width / 2.0;
    let hh = node.bounds.as_ref().unwrap().height / 2.0;

    let nw = quadtree_node_with_bounds(x, y - hh, x + hw, y);
    let ne = quadtree_node_with_bounds(x + hw, y - hh, x + hw * 2.0, y);
    let sw = quadtree_node_with_bounds(x, y - hh * 2.0, x + hw, y - hh);
    let se = quadtree_node_with_bounds(x + hw, y - hh * 2.0, x + hw * 2.0, y - hh);

    if nw.is_none() || ne.is_none() || sw.is_none() || se.is_none() {
        return false;
    }

    node.nw = nw;
    node.ne = ne;
    node.sw = sw;
    node.se = se;

    let old_point = node.point.take();
    let old_key = node.key.take();

    if let Some(old_point) = old_point {
        if let Some(old_key) = old_key {
            return insert(tree, node, old_point, old_key);
        }
    }
    true
}

