pub fn quadtree_insert(tree: &mut Quadtree, x: f64, y: f64, key: Box<dyn Any>) -> bool {
    let point = quadtree_point_new(x, y);
    if point.is_none() {
        return false;
    }
    let point = point.unwrap();
    if !node_contains(tree.root.as_ref().unwrap(), &point) {
        return false;
    }
    if !insert(tree, tree.root.as_mut().unwrap(), point, key) {
        return false;
    }
    tree.length += 1;
    true
}

pub fn quadtree_search(tree: &Quadtree, x: f64, y: f64) -> Option<&Box<QuadtreePoint>> {
    if let Some(root) = &tree.root {
        find(root, x, y)
    } else {
        None
    }
